import{_ as o,o as a,c as t,a4 as r}from"./chunks/framework.gC25n_pp.js";const h=JSON.parse('{"title":"Code Editor API map","description":"Map Code Editor visual surfaces, document and controller APIs, languages, folding, search, LSP coordination, limits, observability, and themes.","frontmatter":{"title":"Code Editor API map","description":"Map Code Editor visual surfaces, document and controller APIs, languages, folding, search, LSP coordination, limits, observability, and themes."},"headers":[],"relativePath":"components/code-editor/api.md","filePath":"components/code-editor/api.md"}'),i={name:"components/code-editor/api.md"};function d(s,e,n,c,l,p){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="code-editor-api-map" tabindex="-1">Code Editor API map <a class="header-anchor" href="#code-editor-api-map" aria-label="Permalink to &quot;Code Editor API map&quot;">​</a></h1><p>The package exposes two visual surfaces plus supporting document, controller, language, protocol, degradation, observability, and theme APIs. Import from <code>@jsvision/code-editor</code> unless a documented language or locale subpath is the explicit subject.</p><h2 id="visual-surfaces" tabindex="-1">Visual surfaces <a class="header-anchor" href="#visual-surfaces" aria-label="Permalink to &quot;Visual surfaces&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Surface</th><th>Role</th></tr></thead><tbody><tr><td><a href="/jsvision/pr-preview/pr-207/api/code-editor/classes/CodeEditor.html"><code>CodeEditor</code></a></td><td>Embeddable focusable editor</td></tr><tr><td><a href="/jsvision/pr-preview/pr-207/api/code-editor/classes/CodeEditorWindow.html"><code>CodeEditorWindow</code></a></td><td>Editor with title, scrollbars, and status</td></tr></tbody></table><p>Supporting public entry points include <code>createDocumentModel</code>, <code>createCodeEditorController</code>, <code>LanguageRegistry</code>, <code>createLanguageScheduler</code>, <code>searchDocument</code>, <code>createInProcessLspSession</code>, <code>createCodeEditorLspCoordinator</code>, <code>classifyDocumentSize</code>, <code>createDegradationState</code>, <code>createObservabilityChannel</code>, and <code>resolveCodeEditorTheme</code>.</p><h2 id="ownership-boundaries" tabindex="-1">Ownership boundaries <a class="header-anchor" href="#ownership-boundaries" aria-label="Permalink to &quot;Ownership boundaries&quot;">​</a></h2><p>The document owns source identity and revisions. The controller owns mutation coordination. The editor owns terminal interaction and viewport presentation. Language adapters and LSP sessions produce bounded analysis; the host owns authorization, persistence, process/network policy, external-change decisions, and final disposal.</p><p>Node-only transports, if used by an application, belong behind the separately documented Node entry point. Browser documentation examples intentionally use bounded in-process seams.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/jsvision/pr-preview/pr-207/components/code-editor/">Overview</a> — choose the visual surface.</li><li><a href="/jsvision/pr-preview/pr-207/components/code-editor/documents-and-lifecycle.html">Documents &amp; lifecycle</a> — understand ownership.</li><li><a href="/jsvision/pr-preview/pr-207/components/code-editor/language-intelligence.html">Language intelligence</a> — compose protocol services.</li><li><a href="/jsvision/pr-preview/pr-207/components/code-editor/host-safety-and-recovery.html">Host safety &amp; recovery</a> — enforce trust boundaries.</li></ul>',10)])])}const m=o(i,[["render",d]]);export{h as __pageData,m as default};
